import { defaultProfile, buildStudyPlan, WEEKDAYS } from './domain.mjs';
import { previewState } from './preview.mjs';

const root = document.querySelector('#app'), modal = document.querySelector('#modal');
const state = { account: null, config: {}, preview: false, route: 'home', busy: false, polling: false, browserOpen: false, frameBusy: false, draftId: null, dirty: false, composer: '', delegateChoice: false };
let toastTimer, frameTimer;

/** Escape all user, course and model content before inserting it into HTML. */
function esc(value) { return String(value ?? '').replace(/[&<>"']/g, /* Replace markup characters, not the text itself. */ char => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' })[char]); }

/** Render consistent local outline icons without fetching third-party assets. */
function icon(name, size = 19) {
  const paths = { chat: 'M21 11.5a8.5 8.5 0 0 1-8.5 8.5H4l-2 2v-9.5A8.5 8.5 0 1 1 21 11.5Z', work: 'M4 5h6l2 2h8v13H4V5Zm4 7h8m-8 4h5', week: 'M4 5h16v15H4V5Zm3-3v6m10-6v6M4 10h16', user: 'M12 12a4 4 0 1 0 0-8 4 4 0 0 0 0 8ZM4 21v-2a8 8 0 0 1 16 0v2', link: 'm8 16 8-8M8 12l-2 2a4 4 0 0 0 6 6l2-2m-4-12 2-2a4 4 0 0 1 6 6l-2 2', card: 'M3 5h18v14H3V5Zm0 5h18m-14 5h4', mcp: 'm8 4-6 8 6 8m8-16 6 8-6 8m-3-18-2 20', arrow: 'M12 20V4m-6 6 6-6 6 6', plus: 'M12 4v16M4 12h16', close: 'm6 6 12 12M6 18 18 6', check: 'm5 12 4 4 10-10', logout: 'M10 4H4v16h6m4-13 5 5-5 5m-6-5h11', globe: 'M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0ZM3 12h18M12 3c5 5 5 13 0 18-5-5-5-13 0-18Z', menu: 'M4 6h16M4 12h16M4 18h16' };
  return `<svg width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[name] || paths.chat}"/></svg>`;
}

/** Call only the same-origin API; raw school login inputs are never placed in app state. */
async function api(op, input, params = '') {
  if (state.preview) throw new Error('This is a preview. Sign up to connect real accounts.');
  const response = await fetch(`/api/index?op=${encodeURIComponent(op)}${params}`, { method: input === undefined ? 'GET' : 'POST', credentials: 'same-origin', headers: input === undefined ? {} : { 'Content-Type': 'application/json' }, ...(input === undefined ? {} : { body: JSON.stringify(input) }) });
  const result = await response.json();
  if (!response.ok) { const error = new Error(result.error || 'Request failed.'); error.status = response.status; throw error; }
  return result;
}

/** Display a transient message without injecting server-supplied markup. */
function toast(message) { const el = document.querySelector('#toast'); el.textContent = message; el.classList.add('show'); clearTimeout(toastTimer); toastTimer = setTimeout(/* Hide the notice after it has been readable. */ () => el.classList.remove('show'), 6000); }

/** Format timestamps in the student's chosen timezone and explicitly mark unknown dates. */
function date(value, time = true) {
  if (!value || !Number.isFinite(Date.parse(value))) return 'No exact date available';
  return new Intl.DateTimeFormat('en-US', { timeZone: state.account?.profile?.timezone || Intl.DateTimeFormat().resolvedOptions().timeZone, month: 'short', day: 'numeric', ...(time ? { hour: 'numeric', minute: '2-digit' } : {}) }).format(new Date(value));
}

/** Keep paid actions separate from free account setup, connection checks and profile edits. */
function paid() { if (state.preview || !state.account?.billing?.active) { toast(state.preview ? 'Preview only. Create an account to use the agent.' : 'Activate your subscription in Billing to use the agent.'); location.hash = state.preview ? 'signup' : 'billing'; return false; } return true; }

/** Refresh persisted account state; polling never silently replaces text being edited. */
async function refresh(render = true) { state.account = await api('state'); if (render && !state.dirty && !state.browserOpen) draw(); }

/** Execute one UI action with a visible error and no false-success fallback. */
async function run(action, button) {
  if (button) button.disabled = true;
  try { return await action(); } catch (error) { toast(error.message); if (error.status === 401) { state.account = null; location.hash = 'login'; draw(); } }
  finally { if (button?.isConnected) button.disabled = false; }
}

/** Navigate without retaining an unsaved editor or accidentally abandoning interactive login. */
function navigate(route) { if (state.dirty && !confirm('Discard your unsaved edits?')) return; state.dirty = false; location.hash = route; }

/** Open an accessible native dialog and focus its first usable control. */
function dialog(title, content, wide = false) { modal.className = wide ? 'wide' : ''; modal.innerHTML = `<div class="dialog-head"><h2 id="dialog-title">${esc(title)}</h2><button class="icon-button" data-close aria-label="Close">${icon('close')}</button></div>${content}`; modal.showModal(); modal.querySelector('[data-close]').onclick = closeDialog; }

/** Close a dialog; a live browser is closed explicitly so login credentials do not linger unnecessarily. */
function closeDialog() {
  if (state.dirty && !confirm('Discard your unsaved edits?')) return;
  state.dirty = false; state.draftId = null;
  if (state.browserOpen) { state.browserOpen = false; clearInterval(frameTimer); run(/* Close the isolated session but do not invent a completed connection. */ async () => { await api('browser/close', { discard: true }); }); }
  modal.close();
}

/** Render the public product page without invented customers, completion rates or live demo claims. */
function landing() {
  root.innerHTML = `<header class="site-header"><a href="#home" class="brand">${icon('work', 24)}canvasly</a><nav><a href="#mcp">Get MCP</a><a href="#login">Log in</a><a class="button dark" href="#signup">Get started</a></nav></header>
  <main id="main" class="landing"><section class="hero"><div class="eyebrow"><span class="status-dot"></span>A little less on your plate</div><h1>Your coursework.<br>Handled, with you.</h1><p>An agent for the work you need to get done.<br>And a study plan that leaves room for real life.</p><div class="hero-actions"><a href="#signup" class="button dark large">Get started ${icon('arrow',18)}</a><button class="button light large" id="preview">Explore the workspace</button></div><div class="hero-note">One account. Website + MCP. $20 per month.</div></section>
  <section class="product-preview" aria-label="Illustrative conversation"><div class="preview-header"><span>${icon('chat')} A quieter evening</span><small>Illustrative example</small></div><div class="sample-message">I’m working late. Prepare my programming assignment and help me find time to study tomorrow.</div><div class="sample-reply"><span class="mini-brand">c</span><div>I’ll prepare the assignment for your review. For the study plan, which days are you working, and when does your shift start?</div></div><div class="sample-task">${icon('work')}<div><strong>Programming assignment</strong><span>Prepare → review → your decision</span></div><span class="tag">Example</span></div><div class="preview-footer">Your time stays yours. You choose what the agent can do.</div></section>
  <section class="features"><article><span>01 / Delegate</span><h2>Give it the task.<br>Not your whole evening.</h2><p>Read the requirements, prepare a complete deliverable, and check its progress from your phone. Supported tasks can continue on the cloud worker after you close your laptop.</p></article><article><span>02 / Understand</span><h2>A schedule built<br>around your life.</h2><p>Work shifts, classes, activities, and how long studying actually takes you. No pretending you have eight free hours every day.</p></article><article><span>03 / Stay in control</span><h2>One workspace.<br>Wherever you think.</h2><p>Use the website or your MCP client. Review saved work, approve context changes, and choose submission permission for each assignment.</p></article></section>
  <section class="pricing-strip"><div><h2>A student agent. One plan.</h2><p>Connect your school before subscribing. Compatibility varies by school and external platform.</p></div><div class="price"><strong>$20</strong><span>/ month</span><a href="#signup" class="button dark">Start with your account</a></div></section>
  <footer>Independent of Canvas, Instructure, OpenAI and your university. Use authorized materials and follow your course rules. <a href="#mcp">MCP connection</a></footer></main>`;
  document.querySelector('#preview').onclick = /* Enter an explicitly labeled sample workspace without an account. */ () => preview();
}

/** Create an illustrative local workspace; no preview record is sent to any live account. */
function preview() {
  const sample = previewState();
  state.preview = true;
  state.account = { ...sample, identity: sample.identity || { name: 'Alex', email: 'alex@example.com' }, profile_revision: 0, snapshot: sample.snapshot || { courses: [], assignments: [], warnings: [] }, messages: [], jobs: [], drafts: [], proposals: [], billing: { active: false }, worker_online: false, config: { mcp_url: location.origin + '/mcp' } };
  location.hash = 'agent'; draw();
}

/** Preserve the authorization request while the student signs into their existing account. */
function nextPath() { return location.pathname === '/oauth/consent' ? location.pathname + location.search : '/#agent'; }

/** Render email/Google signup, login or recovery using the same account for both surfaces. */
function authView(mode) {
  const signup = mode === 'signup', recovery = mode === 'forgot';
  root.innerHTML = `<header class="site-header"><a href="#home" class="brand">${icon('work',24)}canvasly</a><a href="#${signup ? 'login' : 'signup'}">${signup ? 'Already have an account?' : 'Create an account'}</a></header><main id="main" class="auth-page"><h1>${recovery ? 'Reset your password' : signup ? 'Make a little room.' : 'Welcome back.'}</h1><p>${recovery ? 'We’ll send a link to your email.' : 'Your work, your schedule, one account.'}</p>${!state.config.auth_ready ? '<div class="notice">Sign-in is not configured on this deployment yet. The owner needs to add Supabase and encryption settings.</div>' : ''}
  ${recovery ? '' : '<button class="button light full" id="google">Continue with Google</button><div class="separator">or use email</div>'}<form id="auth-form">${signup ? '<label>Your name<input name="name" autocomplete="name" maxlength="100"></label>' : ''}<label>Email<input name="email" type="email" required autocomplete="email"></label>${recovery ? '' : `<label>Password<input name="password" type="password" required minlength="8" autocomplete="${signup ? 'new-password' : 'current-password'}"></label>`}<button class="button dark full" type="submit">${recovery ? 'Send reset link' : signup ? 'Create account' : 'Log in'}</button></form><a class="quiet-link" href="#${recovery ? 'login' : 'forgot'}">${recovery ? 'Back to login' : 'Forgot your password?'}</a><p class="fine-print">${signup ? 'No payment is collected until you choose a subscription. ' : ''}Your school connection is separate from your Canvasly login.</p></main>`;
  document.querySelector('#google')?.addEventListener('click', /* Google credentials are entered on the provider, never in Canvasly fields. */ event => run(/* Execute this user-requested action through the shared error handler. */ async () => { const result = await api('auth/google', { next: nextPath() }); location.assign(result.url); }, event.currentTarget));
  document.querySelector('#auth-form').onsubmit = /* Send credentials only to the same-origin Supabase-backed sign-in endpoint. */ event => {
    event.preventDefault(); const form = event.currentTarget, input = Object.fromEntries(new FormData(form));
    run(/* Execute this user-requested action through the shared error handler. */ async () => { const result = await api(recovery ? 'auth/recover' : 'auth/email', { ...input, signup, next: nextPath() }); form.reset(); if (result.signed_in) { await refresh(false); location.hash = 'agent'; draw(); } else toast(result.message || 'Check your email to confirm your account.'); }, form.querySelector('button[type=submit]'));
  };
}

/** Draw a reusable workspace shell with restrained navigation and an honest worker-status indicator. */
function shell(content, title) {
  const a = state.account, links = [['agent','chat','Agent'],['work','work','My work'],['week','week','My week'],['profile','user','About you'],['connections','link','Connections']];
  root.innerHTML = `<div class="app-shell"><aside class="sidebar"><a class="brand" href="#agent">${icon('work',24)}canvasly</a><div class="nav-label">WORKSPACE</div><nav>${links.map(/* Render only known local navigation targets. */ ([route, glyph, label]) => `<a class="nav-item ${state.route === route ? 'selected' : ''}" href="#${route}">${icon(glyph)}${label}${route === 'work' && a.jobs.filter(/* Keep only entries matching this operation’s selection criteria. */ j => j.status === 'queued' || j.status === 'running').length ? '<span class="nav-count">'+a.jobs.filter(/* Keep only entries matching this operation’s selection criteria. */ j => j.status === 'queued' || j.status === 'running').length+'</span>' : ''}</a>`).join('')}</nav><div class="sidebar-bottom"><a class="nav-item ${state.route === 'mcp' ? 'selected' : ''}" href="#mcp">${icon('mcp')}Get MCP</a><a class="nav-item ${state.route === 'billing' ? 'selected' : ''}" href="#billing">${icon('card')}Billing</a><div class="account"><span class="avatar">${esc((a.profile.name || a.identity.name || a.identity.email || 'S')[0].toUpperCase())}</span><div><strong>${esc(a.profile.name || a.identity.name || 'Your workspace')}</strong><small>${state.preview ? 'Illustrative preview' : a.billing.active ? '$20 monthly plan' : 'Set up your account'}</small></div><button class="icon-button" id="logout" aria-label="${state.preview ? 'Exit preview' : 'Log out'}">${icon('logout')}</button></div></div></aside>
  <div class="workspace"><header class="workspace-header"><button class="icon-button mobile-menu" id="menu" aria-label="Toggle menu">${icon('menu')}</button><span>${esc(title)}</span><span class="connection-status"><i class="status-dot ${a.worker_online ? 'online' : ''}"></i>${state.preview ? 'Preview · no live agent' : a.worker_online ? 'Cloud worker connected' : 'Cloud worker offline'}</span></header>${state.preview ? '<div class="preview-banner">You’re exploring example data. No live work is running. <button id="leave-preview">Create your account</button></div>' : ''}<main id="main" class="page ${state.route === 'agent' ? 'agent-page' : ''}">${content}</main></div></div>`;
  document.querySelector('#menu').onclick = /* Toggle navigation without changing the current task. */ () => document.querySelector('.sidebar').classList.toggle('open');
  document.querySelector('#logout').onclick = /* Explicitly end a real session or discard only local example data. */ event => run(/* Execute this user-requested action through the shared error handler. */ async () => { if (!state.preview) await api('auth/logout', {}); state.preview = false; state.account = null; location.hash = 'home'; draw(); }, event.currentTarget);
  document.querySelector('#leave-preview')?.addEventListener('click', /* Example accounts never merge into authenticated users. */ () => { state.preview = false; state.account = null; location.hash = 'signup'; });
}

/** Render a status badge using text and known classes, not user-controlled class names. */
function badge(value) { const safe = ['queued','running','done','paused','ready','written','submitted','cancelled','needs_manual_check'].includes(value) ? value : 'neutral'; return `<span class="tag ${safe}">${esc(String(value || 'not started').replaceAll('_', ' '))}</span>`; }

/** Show setup guidance only where it helps the student take the next action. */
function onboarding() {
  const a = state.account;
  if (state.preview) return '';
  if (!a.connection) return `<div class="setup-strip">${icon('link')}<div><strong>Start by connecting Canvas.</strong><span>Check that your school works before subscribing.</span></div><a class="button light" href="#connections">Connect Canvas</a></div>`;
  if (!a.billing.active) return `<div class="setup-strip">${icon('check')}<div><strong>Your workspace is ready.</strong><span>Activate Canvasly to start the agent and use MCP.</span></div><a class="button dark" href="#billing">$20 / month</a></div>`;
  if (!a.worker_online) return `<div class="notice">The cloud worker is offline. You can save tasks, but they will not run until it reconnects.</div>`;
  return '';
}

/** Render conversation and real persisted progress; no synthetic typing claims or fake completed jobs. */
function agentView() {
  const a = state.account, active = a.jobs.filter(/* Show only real pending work in the conversation header. */ job => ['queued','running'].includes(job.status));
  const messages = a.messages.length ? `<div class="messages">${a.messages.map(/* Model text stays escaped, including malicious HTML in coursework. */ message => `<article class="message ${message.role === 'user' ? 'from-user' : 'from-agent'}">${message.role === 'user' ? '' : '<span class="mini-brand">c</span>'}<div class="message-text">${esc(message.text)}${message.draft_id ? `<button class="text-button" data-draft="${esc(message.draft_id)}">Open saved work →</button>` : ''}</div></article>`).join('')}</div>` : `<div class="conversation-start"><div class="agent-mark">c<span></span></div><h1>What can I take<br>off your plate?</h1><p>A task to delegate. A topic to understand.<br>A week that needs a little rearranging.</p><div class="prompt-chips"><button data-prompt="Look at my assignments and tell me what needs attention first.">${icon('work',16)}What’s due next?</button><button data-prompt="Help me plan my week around my work shifts. Ask me for any missing details.">${icon('week',16)}Plan around my schedule</button></div></div>`;
  shell(`${onboarding()}${messages}${active.length ? `<div class="live-work">${active.map(/* Queue states are factual, not simulated loading completions. */ job => `<a href="#work"><span class="status-dot ${job.status === 'running' ? 'online' : ''}"></span>${esc(job.title)} <small>${esc(job.status)} · ${esc(job.step)}</small></a>`).join('')}</div>` : ''}<form id="chat-form" class="composer"><label class="sr-only" for="message">Message Canvasly</label><textarea id="message" name="message" rows="2" maxlength="12000" placeholder="Ask Canvasly to help with your day…" required></textarea><div class="composer-bottom"><label class="check-label"><input type="checkbox" name="allow_delegation">Allow this request to queue assignment drafts</label><button class="send" type="submit" aria-label="Send message">${icon('arrow',20)}</button></div></form><p class="composer-note">Submissions need separate, assignment-specific permission. The agent can make mistakes.</p>`, 'Your agent');
  document.querySelector('#message').value = state.composer;
  document.querySelector('[name=allow_delegation]').checked = state.delegateChoice;
  document.querySelector('#message').oninput = /* Preserve an unsent message across background progress refreshes. */ event => { state.composer = event.currentTarget.value; };
  document.querySelector('[name=allow_delegation]').onchange = /* Retain the explicit checkbox selection without granting submission permission. */ event => { state.delegateChoice = event.currentTarget.checked; };
  document.querySelectorAll('[data-prompt]').forEach(/* Suggestions fill the editor; they do not silently send a task. */ button => { button.onclick = /* Handle this explicit user interaction without running an implicit background action. */ () => { state.composer = button.dataset.prompt; document.querySelector('#message').value = state.composer; document.querySelector('#message').focus(); }; });
  document.querySelector('#chat-form').onsubmit = /* Enqueue the message and return immediately; the worker owns subsequent execution. */ event => { event.preventDefault(); if (!paid()) return; const form = event.currentTarget, message = form.elements.message.value; run(/* Execute this user-requested action through the shared error handler. */ async () => { await api('chat', { message, allow_delegation: form.elements.allow_delegation.checked }); state.composer = ''; state.delegateChoice = false; await refresh(); }, form.querySelector('button[type=submit]')); };
  bindDrafts();
}

/** Render saved tasks, drafts and a bounded assignment table with unambiguous completion states. */
function workView() {
  const a = state.account;
  shell(`<div class="page-heading"><div><h1>My work</h1><p>Saved progress. Real receipts. No tab left open.</p></div><button class="button light" id="sync">Sync Canvas</button></div>${onboarding()}
  <section><h2>Agent tasks <span class="muted">${a.jobs.length}</span></h2>${a.jobs.length ? `<div class="task-list">${[...a.jobs].reverse().slice(0,40).map(/* Task status and errors come from durable server checkpoints. */ job => `<article class="task-row"><div class="task-icon">${icon(job.kind === 'sync' ? 'link' : job.kind === 'chat' ? 'chat' : 'work')}</div><div class="grow"><strong>${esc(job.title)}</strong><p>${esc(job.result || job.error || job.step || '')}</p>${job.uncertain ? '<p class="danger-text">Verify the real outcome before taking further action. Automatic retry is disabled.</p>' : ''}</div>${badge(job.status)}<div class="row-actions">${job.draft_id ? `<button class="button light small" data-draft="${esc(job.draft_id)}">Open</button>` : ''}${['queued','running'].includes(job.status) ? `<button class="text-button" data-control="pause" data-job="${esc(job.id)}">Pause</button>` : ''}${job.status === 'paused' && !job.uncertain && job.step !== 'submit' ? `<button class="text-button" data-control="resume" data-job="${esc(job.id)}">Resume</button>` : ''}${job.status === 'paused' ? `<button class="text-button" data-control="cancel" data-job="${esc(job.id)}">Cancel</button>` : ''}${job.step === 'browser' && job.status === 'paused' ? `<button class="text-button" data-browser-job="${esc(job.id)}">Open browser</button>` : ''}</div></article>`).join('')}</div>` : '<div class="empty">No tasks yet. Ask the agent or choose an assignment below.</div>'}</section>
  ${a.drafts.length ? `<section><h2>Saved deliverables</h2><div class="draft-grid">${a.drafts.map(/* Keep the full deliverable behind its explicit editor, not an incomplete summary. */ draft => `<button class="draft-card" data-draft="${esc(draft.id)}">${icon('work',22)}<strong>${esc(draft.title)}</strong>${badge(draft.stage)}</button>`).join('')}</div></section>` : ''}
  <section><div class="section-heading"><h2>Assignments</h2><input type="search" id="assignment-search" placeholder="Find an assignment" aria-label="Find an assignment"></div>${a.snapshot.warnings?.length ? `<div class="notice">${a.snapshot.warnings.map(/* Display collection gaps rather than promising complete course coverage. */ warning => esc(warning)).join('<br>')}</div>` : ''}<div class="assignment-list">${a.snapshot.assignments.length ? a.snapshot.assignments.map(/* Unknown due dates are not silently converted to an invented deadline. */ assignment => `<article class="assignment-row" data-search="${esc(assignment.name.toLowerCase())}"><span class="course-dot"></span><div class="grow"><strong>${esc(assignment.name)}</strong><small>${esc(a.snapshot.courses.find(/* Select the matching entry from this owner-scoped collection. */ c => c.id === assignment.course_id)?.name || 'Course')} · ${esc(date(assignment.due_at))}</small></div>${assignment.submitted ? badge('submitted') : `<button class="button light small" data-delegate="${assignment.id}" data-course="${assignment.course_id}">Delegate</button>`}</article>`).join('') : '<div class="empty">Connect Canvas and sync to see your assignments.</div>'}</div></section>`, 'My work');
  document.querySelector('#sync').onclick = /* Sync is an onboarding capability, not a chargeable model call. */ event => run(/* Execute this user-requested action through the shared error handler. */ async () => { await api('canvas/sync', {}); toast('Sync queued. The cloud worker will update your courses.'); await refresh(); }, event.currentTarget);
  document.querySelector('#assignment-search').oninput = /* Filter visible records without sending private search terms elsewhere. */ event => document.querySelectorAll('[data-search]').forEach(/* Apply this operation to each selected item. */ row => { row.hidden = !row.dataset.search.includes(event.target.value.toLowerCase()); });
  document.querySelectorAll('[data-control]').forEach(/* Use task-specific control requests with no arbitrary job owner IDs. */ button => { button.onclick = /* Handle this explicit user interaction without running an implicit background action. */ () => run(/* Execute this user-requested action through the shared error handler. */ async () => { await api('job/control', { id: button.dataset.job, action: button.dataset.control }); await refresh(); }, button); });
  document.querySelectorAll('[data-delegate]').forEach(/* Open the authorization form before creating a task. */ button => { button.onclick = /* Handle this explicit user interaction without running an implicit background action. */ () => delegateDialog(Number(button.dataset.course), Number(button.dataset.delegate)); });
  document.querySelectorAll('[data-browser-job]').forEach(/* Resume only a paused owner-bound cloud session. */ button => { button.onclick = /* Handle this explicit user interaction without running an implicit background action. */ () => run(/* Execute this user-requested action through the shared error handler. */ async () => { await api('browser/resume', { job_id: button.dataset.browserJob }); browserDialog(); }, button); });
  bindDrafts();
}

/** Ask for explicit scope and submission permission for one selected assignment. */
function delegateDialog(courseId, assignmentId) {
  if (!paid()) return;
  const assignment = state.account.snapshot.assignments.find(/* Display the exact selected assignment. */ item => item.id === assignmentId && item.course_id === courseId);
  dialog('Delegate assignment', `<p>${esc(assignment?.name || 'Selected assignment')}</p><form id="delegate-form"><label>Notes for the agent<textarea name="notes" rows="4" maxlength="10000" placeholder="Requirements, missing context, or how you want the work prepared"></textarea></label><label class="check-label"><input type="checkbox" name="auto">Complete and submit this specific assignment when ready</label><p class="fine-print">Leave unchecked to prepare work for your review. External platforms may save answers immediately; autonomous external work needs explicit submission permission.</p><label id="submit-confirm" hidden>Type SUBMIT to authorize<input name="confirmation" autocomplete="off"></label><button class="button dark full" type="submit">Start task</button></form>`);
  const form = document.querySelector('#delegate-form');
  form.elements.auto.onchange = /* Make advance submission authorization visible, never prechecked. */ () => { document.querySelector('#submit-confirm').hidden = !form.elements.auto.checked; };
  form.onsubmit = /* Queue one task and release the browser so the student can leave. */ event => { event.preventDefault(); run(/* Execute this user-requested action through the shared error handler. */ async () => { await api('delegate', { course_id: courseId, assignment_id: assignmentId, notes: form.elements.notes.value, submit_when_ready: form.elements.auto.checked, confirmation: form.elements.confirmation.value }); modal.close(); await refresh(); toast('Task saved. Check My work from any device.'); }, form.querySelector('button[type=submit]')); };
}

/** Connect all saved-draft buttons to the same versioned editor. */
function bindDrafts() { document.querySelectorAll('[data-draft]').forEach(/* The ID is always resolved against the authenticated account's state. */ button => { button.onclick = /* Handle this explicit user interaction without running an implicit background action. */ () => draftDialog(button.dataset.draft); }); }

/** Render the full deliverable, review and receipt, with edits invalidating prior approval. */
function draftDialog(id) {
  const draft = state.account.drafts.find(/* Prevent stale or foreign IDs from opening an editor. */ item => item.id === id);
  if (!draft) return toast('Refresh to see this draft.');
  state.draftId = id; state.dirty = false;
  const d = draft.deliverable;
  dialog(draft.title, `<div class="draft-meta">${badge(draft.stage)}<span>Version ${draft.version}</span></div>${draft.context_warnings?.length ? `<div class="notice">${draft.context_warnings.map(esc).join('<br>')}</div>` : ''}${!d ? '<p>The agent has not saved a complete deliverable yet.</p>' : `<form id="draft-editor">${d.type === 'online_text_entry' ? `<label>Complete answer<textarea class="deliverable" name="body" rows="15">${esc(d.body)}</textarea></label>` : d.type === 'online_url' ? `<label>Deliverable URL<input name="url" type="url" value="${esc(d.url)}"></label>` : d.files.map(/* Every generated UTF-8 file is editable and individually downloadable. */ (file, i) => `<label>${esc(file.name)}<textarea class="deliverable code" name="file-${i}" rows="12">${esc(file.content)}</textarea></label><button type="button" class="text-button" data-download="${i}">Download ${esc(file.name)}</button>`).join('')}<div class="editor-actions"><button type="submit" class="button light" ${['written','ready'].includes(draft.stage) ? '' : 'disabled'}>Save edits</button><button type="button" class="button light" id="review" ${['written','ready'].includes(draft.stage) ? '' : 'disabled'}>Review saved work</button><button type="button" class="button dark" id="submit-draft" ${draft.stage === 'ready' ? '' : 'disabled'}>Submit saved work</button></div><p id="unsaved-note" class="fine-print">Saving edits invalidates the previous review and submission permission.</p></form>`}${draft.review ? `<section class="review"><h3>Agent review</h3><p class="fine-print">An AI assessment, not a verified grade or executed code test.</p>${(draft.review.criteria || []).map(/* Reviews remain text, not trusted executable markup. */ item => `<p><strong>${esc(item.status)}</strong> · ${esc(item.criterion || item.requirement || item.name || '')} ${esc(item.feedback || item.comment || item.evidence || item.reason || '')}</p>`).join('')}${(draft.review.concerns || []).map(/* Concerns are intentionally not hidden by a completion badge. */ item => `<p class="danger-text">${esc(item)}</p>`).join('')}</section>` : ''}${draft.receipt ? `<section><h3>Submission receipt</h3><pre>${esc(JSON.stringify(draft.receipt, null, 2))}</pre></section>` : ''}`, true);
  const form = document.querySelector('#draft-editor'); if (!form) return;
  form.oninput = /* Block review/submit while the local editor differs from the server's approved bytes. */ () => { state.dirty = true; document.querySelector('#review').disabled = true; document.querySelector('#submit-draft').disabled = true; document.querySelector('#unsaved-note').textContent = 'Unsaved changes. Save before reviewing or submitting.'; };
  form.onsubmit = /* Use the version sent by the server to reject conflicting edits. */ event => { event.preventDefault(); run(/* Execute this user-requested action through the shared error handler. */ async () => { const deliverable = structuredClone(d); if (d.type === 'online_text_entry') deliverable.body = form.elements.body.value; else if (d.type === 'online_url') deliverable.url = form.elements.url.value; else deliverable.files.forEach(/* Apply this operation to each selected item. */ (file, i) => { file.content = form.elements[`file-${i}`].value; }); await api('draft/save', { id, version: draft.version, deliverable }); state.dirty = false; await refresh(false); modal.close(); draftDialog(id); }, form.querySelector('button[type=submit]')); };
  document.querySelector('#review').onclick = /* Queue review of server-saved content, not the unsaved DOM. */ event => run(/* Execute this user-requested action through the shared error handler. */ async () => { await api('draft/review', { id }); modal.close(); state.draftId = null; await refresh(); }, event.currentTarget);
  document.querySelector('#submit-draft').onclick = /* Bind confirmation to the hash displayed for this exact saved version. */ event => run(/* Execute this user-requested action through the shared error handler. */ async () => { const confirmation = prompt('Type SUBMIT to authorize this exact saved deliverable for this assignment.'); if (confirmation !== 'SUBMIT') return; await api('draft/submit', { id, content_hash: draft.content_hash, confirmation }); modal.close(); state.draftId = null; await refresh(); }, event.currentTarget);
  document.querySelectorAll('[data-download]').forEach(/* Save only the student's selected source file; never generated executable commands. */ button => { button.onclick = /* Handle this explicit user interaction without running an implicit background action. */ () => { const index = Number(button.dataset.download), file = d.files[index]; download(file.name, form.elements[`file-${index}`].value); }; });
}

/** Download text as a local file without uploading it to a third-party export service. */
function download(name, text) { const url = URL.createObjectURL(new Blob([text], { type: 'text/plain;charset=utf-8' })); const link = document.createElement('a'); link.href = url; link.download = name; link.click(); setTimeout(/* Release the temporary object after the browser starts saving. */ () => URL.revokeObjectURL(url), 1000); }

/** Render a plan built from confirmed availability, including capacity shortfalls instead of impossible schedules. */
function weekView() {
  const a = state.account, plan = a.plan;
  shell(`<div class="page-heading"><div><h1>My week</h1><p>Time for coursework. Space for everything else.</p></div><button class="button dark" id="plan-week">Build my plan</button></div>${!a.profile.confirmed ? '<div class="notice">Confirm your availability in <a href="#profile">About you</a> first. We won’t guess your work days or study hours.</div>' : ''}<div class="week-summary"><span>${esc(a.profile.timezone)}</span><span>Up to ${a.profile.max_daily_minutes} minutes of study a day</span><a href="#profile">Edit availability →</a></div>${plan ? `<div class="schedule">${plan.sessions.map(/* Sessions are actual timestamps in the student's timezone. */ session => `<article class="schedule-row"><time>${esc(date(session.start))}</time><div><strong>${esc(session.title)}</strong><span>${session.minutes} min · ${esc(session.estimate_basis)}</span></div></article>`).join('') || '<div class="empty">No study sessions were scheduled.</div>'}</div>${plan.unscheduled.length ? `<div class="notice"><strong>Not everything fits.</strong>${plan.unscheduled.map(/* Preserve actionable reasons when capacity or deadlines prevent scheduling. */ item => `<p>${esc(item.title)} · ${item.remaining_minutes} min remaining. ${esc(item.reason)}</p>`).join('')}</div>` : ''}<p class="fine-print">${esc(plan.note)}</p>` : '<div class="empty large-empty">Your week starts with your real availability.<br>Add work, classes and other commitments, then build a plan.</div>'}`, 'My week');
  document.querySelector('#plan-week').onclick = /* Planning is deterministic and does not spend a model call. */ event => run(/* Execute this user-requested action through the shared error handler. */ async () => { if (state.preview) { state.account.plan = buildStudyPlan(a.profile, a.snapshot.assignments); draw(); } else { await api('plan', {}); await refresh(); } }, event.currentTarget);
}

/** Render editable student context without inventing fixed learning-style categories or commitments. */
function profileView() {
  const p = state.account.profile;
  shell(`<div class="page-heading"><div><h1>About you</h1><p>The agent should fit your life—not the other way around.</p></div></div><form id="profile-form" class="settings-form"><section><h2>Your availability</h2><div class="form-grid"><label>Name<input name="name" value="${esc(p.name)}"></label><label>Time zone<input name="timezone" value="${esc(p.timezone)}" placeholder="America/New_York" required></label><label>Study window starts<input name="start" type="time" value="${p.study_window.start}" required></label><label>Study window ends<input name="end" type="time" value="${p.study_window.end}" required></label><label>Maximum study minutes per day<input name="daily" type="number" min="15" max="720" value="${p.max_daily_minutes}"></label><label>Session length in minutes<input name="session" type="number" min="15" max="120" value="${p.session_minutes}"></label><label>Break between sessions<input name="break" type="number" min="0" max="60" value="${p.break_minutes}"></label><label>Explanation preference<select name="format">${['worked-examples','practice-first','short-explanations','visual-explanations','mixed'].map(/* Preferences are editable presentation choices, not a diagnosis. */ option => `<option ${p.preferences.format === option ? 'selected' : ''}>${option}</option>`).join('')}</select></label></div><label>What helps you understand something?<textarea name="notes" rows="3" maxlength="2000">${esc(p.preferences.notes)}</textarea></label><label class="check-label"><input type="checkbox" name="confirmed" ${p.confirmed ? 'checked' : ''}>These are my actual available study hours, not my whole day.</label><button class="button dark" type="submit">Save availability</button></section></form>
  <section><div class="section-heading"><h2>Recurring commitments</h2><button class="button light small" id="add-commitment">${icon('plus',16)}Add</button></div><p class="fine-print">Add work, class, sleep and activities. A shift ending at 01:00 protects the next morning too.</p><div class="commitment-list">${p.commitments.map(/* Show the exact selected days, including an overnight end. */ item => `<article class="assignment-row"><div class="grow"><strong>${esc(item.title)}</strong><small>${item.days.map(/* Transform each source item without changing the original collection. */ day => WEEKDAYS[day]).join(', ')} · ${item.start}–${item.end} · ${item.buffer_minutes} min buffer</small></div><button class="text-button" data-delete-commitment="${esc(item.id)}">Remove</button></article>`).join('') || '<div class="empty">No commitments saved yet.</div>'}</div></section>
  <section><div class="section-heading"><h2>Course settings</h2><button class="button light small" id="course-settings">Set course estimates</button></div><p class="fine-print">Describe the kind of class and your initial time estimate. Your own study check-ins refine it over time.</p>${p.course_settings.map(/* Initial course estimates remain student-provided, not invented from a title. */ item => `<div class="assignment-row"><div class="grow"><strong>${esc(state.account.snapshot.courses.find(/* Select the matching entry from this owner-scoped collection. */ course => String(course.id) === String(item.id))?.name || item.id)}</strong><small>${esc(item.type)} · ${item.baseline_minutes} min starting estimate</small></div></div>`).join('')}</section>
  <section><div class="section-heading"><h2>Learning check-ins</h2><button class="button light small" id="check-in">Add study session</button></div><p class="fine-print">Log your own study time—not the agent’s work. After three observations in a course, duration estimates begin to adapt.</p>${p.observations.slice(-5).reverse().map(/* Keep early estimates visibly grounded in self-reports. */ item => `<div class="assignment-row"><div class="grow"><strong>${esc(item.topic)}</strong><small>Estimated ${item.estimated_minutes} min · actual ${item.actual_minutes} min · understanding ${item.understanding}/5</small></div></div>`).join('')}</section>
  <section><h2>Remembered preferences</h2>${p.memories.map(/* Only approved student context is included here. */ memory => `<div class="assignment-row"><span class="grow">${esc(memory.text)}</span><button class="text-button" data-delete-memory="${esc(memory.id)}">Forget</button></div>`).join('') || '<p class="muted">No approved memories yet.</p>'}${state.account.proposals.map(/* Proposals need an explicit student decision before they alter the plan. */ proposal => `<div class="suggestion"><p>${esc(proposal.text)}</p><button class="button light small" data-memory="${esc(proposal.id)}" data-accept="yes">Remember</button><button class="text-button" data-memory="${esc(proposal.id)}" data-accept="no">Dismiss</button></div>`).join('')}</section>`, 'About you');
  const form = document.querySelector('#profile-form');
  form.oninput = /* Polling must not replace partially edited availability. */ () => { state.dirty = true; };
  form.onsubmit = /* Validate on the server and increment the profile revision. */ event => { event.preventDefault(); const data = new FormData(form); run(/* Execute this user-requested action through the shared error handler. */ async () => { await saveProfile({ ...p, name: data.get('name'), timezone: data.get('timezone'), study_window: { start: data.get('start'), end: data.get('end') }, max_daily_minutes: Number(data.get('daily')), session_minutes: Number(data.get('session')), break_minutes: Number(data.get('break')), preferences: { ...p.preferences, format: data.get('format'), notes: data.get('notes') }, confirmed: data.has('confirmed') }); }, form.querySelector('button[type=submit]')); };
  document.querySelector('#add-commitment').onclick = commitmentDialog;
  document.querySelector('#check-in').onclick = checkInDialog;
  document.querySelector('#course-settings').onclick = courseSettingsDialog;
  document.querySelectorAll('[data-delete-commitment]').forEach(/* Removing a block is a direct student instruction, not a model suggestion. */ button => { button.onclick = /* Handle this explicit user interaction without running an implicit background action. */ () => run(/* Execute this user-requested action through the shared error handler. */ () => saveProfile({ ...p, commitments: p.commitments.filter(/* Keep only entries matching this operation’s selection criteria. */ item => item.id !== button.dataset.deleteCommitment) }), button); });
  document.querySelectorAll('[data-delete-memory]').forEach(/* The student can remove any remembered preference. */ button => { button.onclick = /* Handle this explicit user interaction without running an implicit background action. */ () => run(/* Execute this user-requested action through the shared error handler. */ () => saveProfile({ ...p, memories: p.memories.filter(/* Keep only entries matching this operation’s selection criteria. */ item => item.id !== button.dataset.deleteMemory) }), button); });
  document.querySelectorAll('[data-memory]').forEach(/* Both approval and dismissal are explicit, owner-scoped writes. */ button => { button.onclick = /* Handle this explicit user interaction without running an implicit background action. */ () => run(/* Execute this user-requested action through the shared error handler. */ async () => { await api('memory/decide', { id: button.dataset.memory, accept: button.dataset.accept === 'yes' }); await refresh(); }, button); });
}

/** Save a student-supplied class type and starting duration; later observations refine the estimate. */
function courseSettingsDialog() {
  const courses = state.account.snapshot.courses;
  if (!courses.length) return toast('Sync Canvas before adding course-specific settings.');
  dialog('Course settings', `<form id="course-form"><label>Course<select name="id">${courses.map(/* Offer only actual synced courses. */ course => `<option value="${esc(course.id)}">${esc(course.name)}</option>`).join('')}</select></label><label>Kind of class<input name="type" maxlength="80" placeholder="Programming lab, reading-heavy seminar…" required></label><label>Starting estimate per assignment, minutes<input name="baseline" type="number" min="15" max="600" value="60" required></label><button class="button dark full" type="submit">Save course settings</button></form>`);
  document.querySelector('#course-form').onsubmit = /* Replace the one selected course setting without discarding other courses. */ event => { event.preventDefault(); const form = event.currentTarget, id = form.elements.id.value; run(/* Execute this user-requested action through the shared error handler. */ async () => { const settings = state.account.profile.course_settings.filter(/* Keep only entries matching this operation’s selection criteria. */ item => String(item.id) !== id); settings.push({ id, type: form.elements.type.value, baseline_minutes: Number(form.elements.baseline.value) }); await saveProfile({ ...state.account.profile, course_settings: settings }); modal.close(); }, form.querySelector('button')); };
}

/** Save the complete profile against its known revision and refresh only after a successful write. */
async function saveProfile(profile) { if (state.preview) throw new Error('Profile edits require a real account.'); await api('profile/save', { profile, revision: state.account.profile_revision }); state.dirty = false; await refresh(); toast('Saved. Build a new plan to use these changes.'); }

/** Collect all recurring commitment fields instead of inferring a shift from only its end time. */
function commitmentDialog() {
  dialog('Add a commitment', `<form id="commitment-form"><label>What is it?<input name="title" placeholder="Work shift" required maxlength="100"></label><label>Type<select name="kind">${['work','class','sleep','commute','activity','personal'].map(/* Keep kinds consistent with scheduler validation. */ kind => `<option>${kind}</option>`).join('')}</select></label><fieldset><legend>Days this starts</legend><div class="day-picker">${WEEKDAYS.map(/* Overnight commitments are assigned to their start day. */ (day, index) => `<label><input name="day" type="checkbox" value="${index}">${day}</label>`).join('')}</div></fieldset><div class="form-grid"><label>Starts<input name="start" type="time" required></label><label>Ends<input name="end" type="time" required></label><label>Buffer in minutes<input name="buffer" type="number" min="0" max="180" value="15"></label></div><button class="button dark full" type="submit">Save commitment</button></form>`);
  document.querySelector('#commitment-form').onsubmit = /* Preserve exact day/time input including shifts crossing midnight. */ event => { event.preventDefault(); const form = event.currentTarget, data = new FormData(form); run(/* Execute this user-requested action through the shared error handler. */ async () => { await saveProfile({ ...state.account.profile, commitments: [...state.account.profile.commitments, { id: crypto.randomUUID(), title: data.get('title'), kind: data.get('kind'), days: data.getAll('day').map(Number), start: data.get('start'), end: data.get('end'), buffer_minutes: Number(data.get('buffer')) }] }); modal.close(); }, form.querySelector('button')); };
}

/** Record transparent self-reported study duration and understanding for a selected course. */
function checkInDialog() {
  dialog('How did studying go?', `<form id="checkin-form"><label>Course<select name="course_id" required>${state.account.snapshot.courses.map(/* Use the actual connected course IDs. */ course => `<option value="${course.id}">${esc(course.name)}</option>`).join('')}</select></label><label>Topic<input name="topic" required maxlength="180"></label><div class="form-grid"><label>Expected minutes<input name="estimated_minutes" type="number" min="1" max="1200" value="45" required></label><label>Actual minutes<input name="actual_minutes" type="number" min="1" max="1200" required></label><label>Understanding (1–5)<input name="understanding" type="number" min="1" max="5" value="3" required></label></div><button class="button dark full" type="submit">Save check-in</button></form>`);
  document.querySelector('#checkin-form').onsubmit = /* Agent-generated work is never recorded as evidence of student learning. */ event => { event.preventDefault(); const form = event.currentTarget, data = Object.fromEntries(new FormData(form)); run(/* Execute this user-requested action through the shared error handler. */ async () => { await saveProfile({ ...state.account.profile, observations: [...state.account.profile.observations, { ...data, id: crypto.randomUUID(), at: new Date().toISOString(), format: state.account.profile.preferences.format }] }); modal.close(); }, form.querySelector('button')); };
}

/** Render cloud-browser and optional API connections as complementary, distinct authorizations. */
function connectionsView() {
  const a = state.account, c = a.connection;
  shell(`<div class="page-heading"><div><h1>Connections</h1><p>Your school login stays on your school’s actual page.</p></div></div><section class="connection-card"><div class="section-heading"><div class="inline-heading">${icon('globe',26)}<h2>Canvas</h2></div>${c ? badge(c.needs_login ? 'paused' : 'ready') : '<span class="tag">Not connected</span>'}</div>${c ? `<p><strong>${esc(c.name)}</strong><br><span class="muted">${esc(c.origin)}</span></p><div class="connection-options"><span>${c.browser_ready ? '✓' : '○'} Cloud browser</span><span>${c.api_ready ? '✓' : '○'} Official API</span></div>` : '<p>Open a private cloud browser, sign into your school, then save the connection. The worker can reuse it while your laptop is off, until the school requires you to sign in again.</p>'}<form id="connect-form"><label>Canvas website address<input name="origin" type="url" placeholder="https://your-school.instructure.com" value="${esc(c?.origin || '')}" required></label><div class="row-actions"><button class="button dark" type="submit">${c ? 'Open / reconnect browser' : 'Connect cloud browser'}</button><button type="button" class="button light" id="connect-api">Connect official API</button></div></form><p class="fine-print">API access requires an approved application registration for your institution. A browser login is not an API token. Schools and external tools may require additional authentication or block automation.</p>${c ? '<button class="text-button danger-text" id="disconnect">Disconnect and delete saved connection</button>' : ''}</section><section><h2>Your control</h2><p>Login input goes directly to your isolated Chromium session. It is not sent to the AI model or saved in conversation history. Session cookies are encrypted for later use.</p><p class="fine-print">The cloud worker processes the live login screen and keystrokes. Trust its operator as you would a remote computer. Disconnect to remove saved browser state; revoke any school authorization in Canvas settings too.</p></section>`, 'Connections');
  const form = document.querySelector('#connect-form');
  form.onsubmit = /* Start interactive authentication without a college or email gate. */ event => { event.preventDefault(); run(/* Execute this user-requested action through the shared error handler. */ async () => { await api('browser/start', { origin: form.elements.origin.value }); browserDialog(); }, form.querySelector('button[type=submit]')); };
  document.querySelector('#connect-api').onclick = /* Institution OAuth is optional and never fabricated from browser cookies. */ event => run(/* Execute this user-requested action through the shared error handler. */ async () => { const result = await api('canvas/start', { origin: form.elements.origin.value }); location.assign(result.url); }, event.currentTarget);
  document.querySelector('#disconnect')?.addEventListener('click', /* Require a deliberate removal of the saved credential connection. */ event => run(/* Execute this user-requested action through the shared error handler. */ async () => { if (!confirm('Disconnect Canvas and remove its saved credentials?')) return; const result = await api('canvas/disconnect', {}); await refresh(); toast(result.message); }, event.currentTarget));
}

/** Render an authenticated remote screen/control bridge; this is not a new browser engine or password collector. */
function browserDialog() {
  state.browserOpen = true;
  dialog('Your cloud browser', `<p class="fine-print">Verify the address before signing in. Click the real school form on the screen; use the private input below to type into the focused field. Passwords and verification codes are not sent to the agent.</p><div class="browser-toolbar"><button class="button light small" id="browser-back">Back</button><select id="browser-tabs" aria-label="Browser tabs"></select><button class="button light small" id="browser-refresh">Refresh screen</button></div><div class="browser-address" id="browser-address">Connecting…</div><div class="remote-screen"><img id="browser-screen" alt="Live school website in your isolated cloud browser" draggable="false"><div id="screen-placeholder">Loading your session…</div></div><form id="browser-input"><label>Private keyboard input<input name="text" type="password" autocomplete="off" placeholder="Click a field on the screen, then type here" maxlength="4000"></label><div class="row-actions"><button class="button light" type="submit">Type into focused field</button><button class="button light" type="button" data-browser-key="Tab">Tab</button><button class="button light" type="button" data-browser-key="Enter">Enter</button><button class="button light" type="button" data-browser-key="Control+A">Select all</button><button class="button light" type="button" data-browser-key="Backspace">Backspace</button><button class="button light" type="button" id="scroll-down">Scroll down</button><button class="button light" type="button" id="scroll-up">Scroll up</button></div></form><div class="browser-finish"><span>Once Canvas shows your courses, save the connection.</span><button class="button dark" id="browser-finish">I’m signed in — save connection</button></div>`, true);
  document.querySelector('#browser-screen').onclick = /* Translate display coordinates into the actual 1280×800 browser viewport. */ event => { const box = event.currentTarget.getBoundingClientRect(); browserInput({ action: 'click', x: (event.clientX - box.left) * 1280 / box.width, y: (event.clientY - box.top) * 800 / box.height }); };
  document.querySelector('#browser-input').onsubmit = /* Clear the private input before sending and never retain it in shared UI state. */ event => { event.preventDefault(); const input = event.currentTarget.elements.text, text = input.value; input.value = ''; browserInput({ action: 'type', text }); };
  document.querySelectorAll('[data-browser-key]').forEach(/* Only the server's small keyboard allowlist is exposed. */ button => { button.onclick = /* Handle this explicit user interaction without running an implicit background action. */ () => browserInput({ action: 'key', key: button.dataset.browserKey }); });
  document.querySelector('#browser-back').onclick = /* History navigation stays inside the isolated session. */ () => browserInput({ action: 'back' });
  document.querySelector('#scroll-down').onclick = /* Scroll the browser, not the private keyboard field. */ () => browserInput({ action: 'scroll', y: 650 });
  document.querySelector('#scroll-up').onclick = /* Support long authentication pages on phone screens. */ () => browserInput({ action: 'scroll', y: -650 });
  document.querySelector('#browser-tabs').onchange = /* External LTI tabs share only this student's isolated context. */ event => browserInput({ action: 'tab', index: Number(event.target.value) });
  document.querySelector('#browser-refresh').onclick = /* Refresh a screenshot without reloading an authentication form. */ () => updateFrame();
  document.querySelector('#browser-finish').onclick = /* Verify a real Canvas user before persisting encrypted storage. */ event => run(/* Execute this user-requested action through the shared error handler. */ async () => { await api('browser/finish', {}); state.browserOpen = false; clearInterval(frameTimer); modal.close(); await api('canvas/sync', {}); await refresh(); toast('Canvas connected. Course sync is queued.'); }, event.currentTarget);
  updateFrame(); clearInterval(frameTimer); frameTimer = setInterval(/* Poll only while the account owner is looking at the session. */ () => updateFrame(), 2500);
}

/** Relay one owner-entered browser action and then refresh its visible result. */
async function browserInput(input) { await run(/* Execute this user-requested action through the shared error handler. */ async () => { await api('browser/input', input); await updateFrame(); }); }

/** Fetch private screenshot bytes without storing them, recording them or adding them to chat. */
async function updateFrame() {
  if (!state.browserOpen || state.frameBusy) return; state.frameBusy = true;
  try { const frame = await api('browser/frame', {}); if (!state.browserOpen) return; const image = document.querySelector('#browser-screen'); image.src = frame.image; image.hidden = false; document.querySelector('#screen-placeholder').hidden = true; document.querySelector('#browser-address').textContent = frame.url; const tabs = document.querySelector('#browser-tabs'), current = tabs.value; tabs.innerHTML = frame.pages.map(/* Escape actual external URLs before rendering tab names. */ (url, i) => `<option value="${i}" ${url === frame.url ? 'selected' : ''}>${esc(new URL(url).hostname || 'New tab')} · ${i + 1}</option>`).join(''); }
  catch (error) { if (state.browserOpen && error.status !== 409) toast(error.message); }
  finally { state.frameBusy = false; }
}

/** Render the one real paid plan, actual metered usage and a Stripe-managed cancellation path. */
function billingView() {
  const b = state.account.billing;
  shell(`<div class="page-heading"><div><h1>Billing</h1><p>One subscription for the website and MCP.</p></div></div><section class="plan-card"><span class="eyebrow">CANVASLY</span><h2>$20<span> / month</span></h2><p>Your student agent, coursework workspace, and personal study plan.</p><div class="plan-features"><span>${icon('check')}Website + authenticated MCP</span><span>${icon('check')}Saved tasks and deliverables</span><span>${icon('check')}Cloud execution when the worker is online</span><span>${icon('check')}Schedule built around your commitments</span></div>${!state.account.connection ? '<div class="notice">Connect your school first to check compatibility before paying.</div>' : ''}<button class="button dark full" id="subscribe">${b.active ? 'Manage subscription' : 'Subscribe for $20 / month'}</button><p class="fine-print">Recurring monthly subscription. Cancel in the billing portal. Taxes, when configured and applicable, are shown at checkout. Usage allowances are configurable; this is not an unlimited-use promise.</p></section>${b.status !== 'none' ? `<section class="billing-details"><h2>Your subscription</h2><p>Status: <strong>${esc(b.status || 'not active')}</strong></p>${b.period_end ? `<p>${b.cancel_at_period_end ? 'Access ends' : 'Current period ends'} ${esc(date(b.period_end, false))}</p>` : ''}<p>Model calls this period: ${b.model_calls || 0}${b.model_call_limit ? ` of ${b.model_call_limit}` : ''}</p>${!b.active ? '<button class="button light" id="manage-existing">Manage existing billing</button>' : ''}</section>` : ''}<p class="fine-print">A successful checkout redirect is not proof of payment. Access updates after Stripe confirms the subscription.</p>`, 'Billing');
  document.querySelector('#subscribe').onclick = /* Stripe hosts payment details; this application never collects card numbers. */ event => run(/* Execute this user-requested action through the shared error handler. */ async () => { const result = await api(b.active ? 'billing/portal' : 'billing/checkout', {}); location.assign(result.url); }, event.currentTarget);
  document.querySelector('#manage-existing')?.addEventListener('click', /* Let past-due or cancelled customers inspect invoices and payment methods. */ event => run(/* Execute this user-requested action through the shared error handler. */ async () => { const result = await api('billing/portal', {}); location.assign(result.url); }, event.currentTarget));
}

/** Show the remote MCP connection and existing grants without asking for a personal API token. */
function mcpView() {
  const content = `<div class="page-heading"><div><span class="eyebrow">ONE ACCOUNT. TWO WAYS IN.</span><h1>Bring Canvasly<br>into your AI workspace.</h1><p>Connect once, then use the same courses, profile and saved tasks.</p></div></div><section class="mcp-card">${icon('mcp',32)}<h2>Remote MCP</h2><label>Server URL<div class="copy-row"><input id="mcp-url" readonly value="${esc(state.config.mcp_url || location.origin + '/mcp')}"><button class="button light" id="copy-mcp">Copy</button></div></label><p>In a client that supports remote MCP with OAuth, add this server URL. Canvasly will open a sign-in and consent page. Use your existing account, then approve the requested permissions.</p><p>The initial sign-in is normally one-time. Refresh tokens keep the connection active until access expires or you revoke it. ChatGPT availability also depends on your client and workspace settings.</p><p class="fine-print">An active subscription is required for tools. Unattended jobs use Canvasly’s API account, not your ChatGPT subscription, and continue on the cloud worker.</p>${state.account ? '<div id="mcp-grants"></div>' : '<a class="button dark" href="#signup">Create your account</a>'}</section>`;
  if (state.account) shell(content, 'Get MCP'); else root.innerHTML = `<header class="site-header"><a class="brand" href="#home">${icon('work',24)}canvasly</a><a class="button light" href="#login">Log in</a></header><main id="main" class="standalone">${content}</main>`;
  document.querySelector('#copy-mcp').onclick = /* Copy only a public endpoint, never a bearer credential. */ event => run(/* Execute this user-requested action through the shared error handler. */ async () => { await navigator.clipboard.writeText(document.querySelector('#mcp-url').value); toast('MCP URL copied.'); }, event.currentTarget);
  if (state.account && !state.preview) run(/* Execute this user-requested action through the shared error handler. */ async () => { const grants = await api('mcp/grants'), target = document.querySelector('#mcp-grants'); if (!target) return; target.innerHTML = `<h3>Connected clients</h3>${grants.filter(/* Keep only entries matching this operation’s selection criteria. */ grant => !grant.revoked_at).map(/* Permit revocation of each grant without deleting the student's account. */ grant => `<div class="assignment-row"><span class="grow">MCP connection · ${esc(date(grant.created_at, false))}</span><button class="text-button" data-revoke="${esc(grant.id)}">Revoke</button></div>`).join('') || '<p class="muted">No active MCP connections yet.</p>'}`; target.querySelectorAll('[data-revoke]').forEach(/* Revocation affects access and future refresh immediately. */ button => { button.onclick = /* Handle this explicit user interaction without running an implicit background action. */ () => run(/* Execute this user-requested action through the shared error handler. */ async () => { await api('mcp/revoke', { id: button.dataset.revoke }); mcpView(); }, button); }); });
}

/** Present client-specific OAuth consent only after normal Canvasly sign-in. */
async function consentView() {
  root.innerHTML = '<main id="main" class="auth-page"><div class="brand">canvasly</div><p>Loading connection request…</p></main>';
  const id = new URLSearchParams(location.search).get('authorization_id');
  try {
    const details = await api('oauth/consent', undefined, `&authorization_id=${encodeURIComponent(id || '')}`);
    root.innerHTML = `<main id="main" class="auth-page"><div class="brand">canvasly</div><h1>Connect ${esc(details.name)}?</h1><p>You are signed in as ${esc(state.account.identity.email)}.</p><section class="notice"><strong>This client is requesting:</strong>${details.scopes.map(/* Explain scope effects without implying access to credentials. */ scope => `<p>${scope === 'canvasly.read' ? 'Read your student context, coursework and task status.' : 'Queue work, stage drafts, propose context changes, and perform assignment-specific submissions only when you explicitly authorize them.'}</p>`).join('')}</section><p class="fine-print">Return address: ${esc(new URL(details.redirect_uri).origin)}. Only connect clients you trust. School passwords and session credentials are not exposed as MCP tools.</p><button class="button dark full" id="approve-client">Allow connection</button><button class="button light full" id="deny-client">Cancel</button></main>`;
    document.querySelector('#approve-client').onclick = /* Consent binds the verified user to this exact stored request and callback. */ event => run(/* Execute this user-requested action through the shared error handler. */ async () => { const result = await api('oauth/decision', { id, approve: true }); location.assign(result.url); }, event.currentTarget);
    document.querySelector('#deny-client').onclick = /* Denial returns only an OAuth access_denied result. */ event => run(/* Execute this user-requested action through the shared error handler. */ async () => { const result = await api('oauth/decision', { id, approve: false }); location.assign(result.url); }, event.currentTarget);
  } catch (error) { root.innerHTML = `<main id="main" class="auth-page"><h1>Connection unavailable</h1><p>${esc(error.message)}</p><a href="/#agent" class="button light">Return to Canvasly</a></main>`; }
}

/** Update a password only after Supabase has authenticated the recovery session. */
function resetView() {
  shell('<div class="page-heading"><div><h1>Choose a new password</h1></div></div><form id="reset-form" class="settings-form"><label>New password<input name="password" type="password" autocomplete="new-password" minlength="8" required></label><button class="button dark">Save password</button></form>', 'Account');
  document.querySelector('#reset-form').onsubmit = /* Keep the new password out of application state and logs. */ event => { event.preventDefault(); const form = event.currentTarget; run(/* Execute this user-requested action through the shared error handler. */ async () => { await api('auth/password', { password: form.elements.password.value }); form.reset(); toast('Password updated.'); location.hash = 'agent'; }, form.querySelector('button')); };
}

/** Route public pages and protected workspace views while preserving a pending MCP consent request. */
function draw() {
  state.route = location.hash.slice(1) || (state.account ? 'agent' : 'home');
  if (['signup','login','forgot'].includes(state.route) && state.preview) { state.preview = false; state.account = null; }
  if (location.pathname === '/oauth/consent') { if (!state.account) return authView(state.route === 'signup' ? 'signup' : 'login'); return consentView(); }
  if (state.route === 'home') return landing();
  if (['signup','login','forgot'].includes(state.route) && !state.account) return authView(state.route);
  if (state.route === 'mcp') return mcpView();
  if (!state.account) return authView('login');
  const views = { agent: agentView, work: workView, week: weekView, profile: profileView, connections: connectionsView, billing: billingView, 'reset-password': resetView };
  (views[state.route] || agentView)();
}

/** Start the UI without requiring keys to render the public site; live errors remain explicit. */
async function boot() {
  try { state.config = await api('config'); } catch { state.config = {}; }
  try { await refresh(false); } catch (error) { if (error.status !== 401 && location.hash && location.hash !== '#home') toast(error.message); }
  draw();
  const error = new URLSearchParams(location.search).get('connection_error'); if (error) toast(error);
  setInterval(/* Poll durable progress only while needed; never overwrite an editor or private browser screen. */ async () => {
    if (!state.account || state.preview || state.polling || state.dirty || state.browserOpen || modal.open || document.hidden) return;
    state.polling = true;
    try { const version = state.account.version, oldBilling = JSON.stringify(state.account.billing), worker = state.account.worker_online; await refresh(false); if (version !== state.account.version || oldBilling !== JSON.stringify(state.account.billing) || worker !== state.account.worker_online) draw(); }
    catch { /* The next successful poll restores progress; no fake offline result is substituted. */ }
    finally { state.polling = false; }
  }, 6000);
}

window.addEventListener('hashchange', /* Preserve unsaved work when navigation is canceled. */ event => { if (state.dirty && !confirm('Discard your unsaved edits?')) { history.replaceState(null, '', event.oldURL); return; } state.dirty = false; draw(); });
modal.addEventListener('cancel', /* Escape closes interactive sessions through the same cleanup path. */ event => { event.preventDefault(); closeDialog(); });
window.addEventListener('beforeunload', /* Warn only about unsaved edits, not durable tasks running on the server. */ event => { if (state.dirty) { event.preventDefault(); event.returnValue = ''; } });
boot();
